//! Runs `test-vectors/store/` against the Rust store/0 formats. The vectors
//! are generated by the independent JavaScript reference
//! (`tools/reference/log.mjs`, via `tools/make-vectors.mjs`), so agreement
//! here means two implementations agree.

use std::fs;
use std::path::{Path, PathBuf};

use evidence_core::canon::{canonicalize, sha256_hex};
use evidence_core::json::{self, Value};
use evidence_log::merkle::{self, Digest};
use evidence_log::{Entry, FindingCode, Kind};

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../test-vectors/store")
}

fn load(name: &str) -> Value {
    let path = root().join(name);
    json::parse(&fs::read(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display())))
        .unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn s<'a>(v: &'a Value, key: &str) -> &'a str {
    v.get(key)
        .and_then(Value::as_str)
        .unwrap_or_else(|| panic!("{key} is not a string in {}", canonicalize(v)))
}

fn u(v: &Value, key: &str) -> u64 {
    match v.get(key) {
        Some(Value::Number(n)) if *n >= 0.0 && n.fract() == 0.0 => *n as u64,
        _ => panic!("{key} is not an integer in {}", canonicalize(v)),
    }
}

fn list<'a>(v: &'a Value, key: &str) -> &'a [Value] {
    v.get(key)
        .and_then(Value::as_array)
        .unwrap_or_else(|| panic!("{key} is not an array in {}", canonicalize(v)))
}

fn digest(text: &str) -> Digest {
    merkle::from_text(text).unwrap_or_else(|| panic!("{text:?} is not a sha256: digest"))
}

fn digests(v: &Value, key: &str) -> Vec<Digest> {
    list(v, key)
        .iter()
        .map(|d| digest(d.as_str().expect("digest text")))
        .collect()
}

fn finish(kind: &str, failures: Vec<String>, total: usize) {
    assert!(total > 0, "no {kind} vectors found");
    assert!(
        failures.is_empty(),
        "{} of {total} {kind} vectors failed:\n  {}",
        failures.len(),
        failures.join("\n  ")
    );
}

#[test]
fn entry_vectors() {
    let file = load("entries.json");
    let valid = list(&file, "valid");
    let invalid = list(&file, "invalid");
    let mut failures = Vec::new();

    // What section 10 of the M1 spec asks the valid cases to cover.
    let (mut genesis, mut attestation, mut nine_digits, mut epoch_7) = (false, false, false, false);

    for c in valid {
        let name = s(c, "name");
        let want_canonical = s(c, "canonical");
        let want_hash = s(c, "hash");
        let value = c.get("entry").expect("entry");
        let entry = match Entry::from_value(value) {
            Ok(e) => e,
            Err(code) => {
                failures.push(format!("{name}: rejected with {code}"));
                continue;
            }
        };
        let mut problems = Vec::new();
        if entry.canonical() != want_canonical {
            problems.push(format!("canonical {}", entry.canonical()));
        }
        if canonicalize(value) != want_canonical {
            problems.push("the core canonicalises the entry differently".to_string());
        }
        if entry.hash() != want_hash {
            problems.push(format!("hash {}", entry.hash()));
        }
        if sha256_hex(want_canonical.as_bytes()) != want_hash {
            problems.push("hash is not sha256 of canonical".to_string());
        }
        match Entry::parse(want_canonical.as_bytes()) {
            Ok(again) if again == entry => {}
            other => problems.push(format!("canonical text parses to {other:?}")),
        }
        if !problems.is_empty() {
            failures.push(format!("{name}: {}", problems.join("; ")));
        }

        genesis |= entry.seq == 1 && entry.log == entry.reference && entry.log == entry.prev;
        attestation |= entry.kind == Kind::Attestation;
        nine_digits |= entry.received_at.len() == "2026-11-26T00:00:00.123456789Z".len();
        epoch_7 |= entry.epoch == 7;
    }
    assert!(genesis, "no genesis entry (seq 1, log = ref = prev)");
    assert!(attestation, "no attestation entry");
    assert!(nine_digits, "no received_at with 9 fraction digits");
    assert!(epoch_7, "no entry with epoch 7");

    for c in invalid {
        let name = s(c, "name");
        let want = s(c, "error");
        if want != FindingCode::EntryInvalid.as_str() {
            failures.push(format!("{name}: unexpected error code {want}"));
            continue;
        }
        match Entry::parse(s(c, "input").as_bytes()) {
            Err(code) if code.as_str() == want => {}
            other => failures.push(format!("{name}: got {other:?}, want {want}")),
        }
    }
    assert!(!invalid.is_empty(), "no invalid entry vectors");
    finish("entry", failures, valid.len() + invalid.len());
}

#[test]
fn merkle_vectors() {
    let file = load("merkle.json");
    let trees = file.as_array().expect("an array of trees");
    let mut failures = Vec::new();
    let (mut total, mut negatives) = (0, 0);

    for t in trees {
        let name = s(t, "name");
        let leaves: Vec<Digest> = list(t, "leaves")
            .iter()
            .map(|l| merkle::leaf_hash(l.as_str().expect("leaf text").as_bytes()))
            .collect();
        let size = leaves.len() as u64;
        let want_root = digest(s(t, "root"));
        total += 1;
        if merkle::root(&leaves) != want_root {
            failures.push(format!(
                "{name}: root {}",
                merkle::to_text(&merkle::root(&leaves))
            ));
        }

        for p in list(t, "inclusion") {
            total += 1;
            let index = u(p, "index");
            let proof = digests(p, "proof");
            let valid = p.get("valid") == Some(&Value::Bool(true));
            negatives += usize::from(!valid);
            let leaf = match usize::try_from(index).ok().and_then(|i| leaves.get(i)) {
                Some(l) => *l,
                // Out of range: the leaf that would be there.
                None => merkle::leaf_hash(format!("leaf-{index}").as_bytes()),
            };
            if valid && merkle::inclusion_proof(&leaves, index) != proof {
                failures.push(format!("{name}: inclusion proof for index {index} differs"));
            }
            let got = merkle::verify_inclusion(&leaf, index, size, &proof, &want_root);
            if got != valid {
                failures.push(format!(
                    "{name}: inclusion index {index} verified {got}, want {valid}"
                ));
            }
        }

        for p in list(t, "consistency") {
            total += 1;
            let old_size = u(p, "old_size");
            let old_root = digest(s(p, "old_root"));
            let proof = digests(p, "proof");
            let valid = p.get("valid") == Some(&Value::Bool(true));
            negatives += usize::from(!valid);
            if valid {
                if merkle::consistency_proof(&leaves, old_size) != proof {
                    failures.push(format!("{name}: consistency proof from {old_size} differs"));
                }
                let old = usize::try_from(old_size).unwrap_or(usize::MAX);
                if old > leaves.len() || merkle::root(&leaves[..old]) != old_root {
                    failures.push(format!("{name}: old root for {old_size} differs"));
                }
            }
            let got = merkle::verify_consistency(old_size, size, &old_root, &want_root, &proof);
            if got != valid {
                failures.push(format!(
                    "{name}: consistency from {old_size} verified {got}, want {valid}"
                ));
            }
        }
    }
    assert!(negatives > 0, "no negative Merkle cases");
    finish("merkle", failures, total);
}
